internal_exr_check_magic (exr_context_t ctxt)
{
    uint32_t     flags;
    uint64_t     initpos;
    exr_result_t rv = EXR_ERR_UNKNOWN;

    rv = read_magic_and_flags (ctxt, &flags, &initpos);
